// CUDA WebShader 0.1.1. Generated from kernel mixture_solid.
@group(0) @binding(0) var<storage, read> b_field: array<vec4<f32>>;
@group(0) @binding(1) var<storage, read> b_flux: array<vec4<f32>>;
@group(0) @binding(2) var<storage, read> b_input: array<vec4<f32>>;
@group(0) @binding(3) var<storage, read_write> b_output: array<vec4<f32>>;
@group(0) @binding(4) var<storage, read> b_structure: array<f32>;
@group(0) @binding(5) var<storage, read_write> b_outputStructure: array<f32>;
struct CWParams {
  p_n: i32,
  cw_pad_4: u32,
  cw_pad_8: u32,
  cw_pad_12: u32,
}
@group(0) @binding(6) var<uniform> cw_params: CWParams;
const cw_block_size: vec3<u32> = vec3<u32>(128u, 1u, 1u);

fn cw_divide_f32(a: f32, b: f32) -> f32 { let q = a / b; if ((bitcast<u32>(q) & 0x7f800000u) == 0x7f800000u || (bitcast<u32>(q) & 0x7fffffffu) == 0u || (bitcast<u32>(b) & 0x7f800000u) == 0x7f800000u) { return q; } let residual = fma(-q, b, a); return q + residual / b; }

alias cw_f64 = vec2<u32>;










struct CWDoubleParts { significand: vec2<u32>, exponent: i32, }

// Input has its leading bit at bit 55 and three guard/round/sticky bits.














// Restoring square root: 56 root bits include guard/round/sticky for binary64.




fn f_sat(cw_arg_x: f32, cw_thread: vec3<u32>, cw_block: vec3<u32>, cw_grid: vec3<u32>) -> f32 {
  var v_x: f32 = cw_arg_x;
  return min(1.0f, max(0.0f, v_x));
}














@compute @workgroup_size(128, 1, 1)
fn main(
  @builtin(local_invocation_id) cw_thread: vec3<u32>,
  @builtin(workgroup_id) cw_block: vec3<u32>,
  @builtin(num_workgroups) cw_grid: vec3<u32>
) {
  var v_i: i32 = i32(((cw_block.x * cw_block_size.x) + cw_thread.x));
  if ((v_i >= (cw_params.p_n * cw_params.p_n))) {
    return;
  }
  var v_x: i32 = (v_i % cw_params.p_n);
  var v_z: i32 = (v_i / cw_params.p_n);
  var v_f: vec4<f32> = b_flux[v_i];
  var v_outgoing: f32 = (((v_f.x + v_f.y) + v_f.z) + v_f.w);
  var v_retained: f32 = max(0.0f, (b_field[v_i].x - v_outgoing));
  var v_old: vec4<f32> = b_input[v_i];
  var v_bound: f32 = (v_old.x * (1.0f - min(1.0f, cw_divide_f32(v_outgoing, max(b_field[v_i].x, 1e-7f)))));
  var v_pigment: f32 = (v_old.w * v_retained);
  var v_knead: f32 = (v_old.z * v_retained);
  var v_mass: f32 = v_retained;
  var v_strength: f32 = (b_structure[v_i] * v_retained);
  if ((v_x > 0i)) {
    var v_q: f32 = b_flux[(v_i - 1i)].y;
    v_mass = (v_mass + v_q);
    v_bound = (v_bound + cw_divide_f32((b_input[(v_i - 1i)].x * v_q), max(b_field[(v_i - 1i)].x, 1e-7f)));
    v_pigment = (v_pigment + (b_input[(v_i - 1i)].w * v_q));
    v_strength = (v_strength + (b_structure[(v_i - 1i)] * v_q));
    v_knead = (v_knead + (b_input[(v_i - 1i)].z * v_q));
  }
  if ((v_x < (cw_params.p_n - 1i))) {
    var v_q: f32 = b_flux[(v_i + 1i)].x;
    v_mass = (v_mass + v_q);
    v_bound = (v_bound + cw_divide_f32((b_input[(v_i + 1i)].x * v_q), max(b_field[(v_i + 1i)].x, 1e-7f)));
    v_pigment = (v_pigment + (b_input[(v_i + 1i)].w * v_q));
    v_strength = (v_strength + (b_structure[(v_i + 1i)] * v_q));
    v_knead = (v_knead + (b_input[(v_i + 1i)].z * v_q));
  }
  if ((v_z > 0i)) {
    var v_q: f32 = b_flux[(v_i - cw_params.p_n)].w;
    v_mass = (v_mass + v_q);
    v_bound = (v_bound + cw_divide_f32((b_input[(v_i - cw_params.p_n)].x * v_q), max(b_field[(v_i - cw_params.p_n)].x, 1e-7f)));
    v_pigment = (v_pigment + (b_input[(v_i - cw_params.p_n)].w * v_q));
    v_strength = (v_strength + (b_structure[(v_i - cw_params.p_n)] * v_q));
    v_knead = (v_knead + (b_input[(v_i - cw_params.p_n)].z * v_q));
  }
  if ((v_z < (cw_params.p_n - 1i))) {
    var v_q: f32 = b_flux[(v_i + cw_params.p_n)].z;
    v_mass = (v_mass + v_q);
    v_bound = (v_bound + cw_divide_f32((b_input[(v_i + cw_params.p_n)].x * v_q), max(b_field[(v_i + cw_params.p_n)].x, 1e-7f)));
    v_pigment = (v_pigment + (b_input[(v_i + cw_params.p_n)].w * v_q));
    v_strength = (v_strength + (b_structure[(v_i + cw_params.p_n)] * v_q));
    v_knead = (v_knead + (b_input[(v_i + cw_params.p_n)].z * v_q));
  }
  var cw_tmp_0: f32;
  if ((v_mass > 0.000001f)) {
    cw_tmp_0 = f_sat(cw_divide_f32(v_strength, v_mass), cw_thread, cw_block, cw_grid);
  } else {
    cw_tmp_0 = 1.0f;
  }
  b_outputStructure[v_i] = cw_tmp_0;
  var cw_tmp_1: f32;
  if ((v_mass > 0.00001f)) {
    cw_tmp_1 = cw_divide_f32(v_knead, v_mass);
  } else {
    cw_tmp_1 = v_old.z;
  }
  var cw_tmp_2: f32;
  if ((v_mass > 0.00001f)) {
    cw_tmp_2 = cw_divide_f32(v_pigment, v_mass);
  } else {
    cw_tmp_2 = v_old.w;
  }
  b_output[v_i] = vec4<f32>(v_bound, v_old.y, cw_tmp_1, cw_tmp_2);
}
